namespace ghidra.app.plugin.core.decompile.actions;

using docking.action;
using ghidra.app.plugin.core.decompile;
using ghidra.app.util;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;
using ghidra.program.model.scalar;
using ghidra.util;
using ghidra.util;

/**
 * Convert a selected constant in the decompiler to a binary representation.
 */
public class ConvertBinaryAction : ConvertConstantAction {

	public ConvertBinaryAction(DecompilePlugin plugin) : base(plugin, "Convert To Binary", EquateSymbol.FORMAT_BIN)
    {
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "ActionConvert"));
		setPopupMenuData(new MenuData(new string[] { "Binary" }, "Decompile"));
	}

	/* @Override */
	public string getMenuPrefix() {
		return "Binary: ";
	}

	/* @Override */
	public string getMenuDisplay(Scalar scalar, Program program) {
		long v;
		string prefix = "0b";
		if (scalar.isSigned()) {
			v = scalar.getSignedValue();
			if (v < 0) {
				v = -v;
				prefix = "-0b";
			}
		}
		else {
			v = scalar.getUnsignedValue();

		}
		string bitString = Long.toBinaryString(v);
		int bitlen = bitString.length();
		if (bitlen <= 8) {
			bitlen = 8;
		}
		else if (bitlen <= 16) {
			bitlen = 16;
		}
		else if (bitlen <= 32) {
			bitlen = 32;
		}
		else {
			bitlen = 64;
		}
		return prefix + StringUtilities.pad(bitString, '0', bitlen);
	}

	/* @Override */
	public string getEquateName(Scalar scalar, Program program) {
		string valueStr = Long.toBinaryString(scalar.getValue());
		valueStr = StringUtilities.pad(valueStr, '0', scalar.bitLength());
		return valueStr + "b";
	}
}
